//! The builder port, checked against the pinned Python reference's own answers.
//!
//! `tests/fixtures/phase5b/oracle.json` is generated by `parity/tools/gen_phase5b_fixtures.py`
//! running the archive's code, so every preview row, refusal message, operation manifest, file
//! digest and assembled tool manifest here is the oracle's verdict — not an expectation written
//! by hand. A divergence fails this test instead of reaching a tenant.

use serde_json::{Map, Value};
use sha2::{Digest as _, Sha256};

use mcp_server_rs::builder::models::{
    BindRequest, ImportRequest, OperationOverride, SpecFetchRequest, ToolCreate, ToolOperation,
};
use mcp_server_rs::builder::openapi::{Selection, import_openapi, list_operations};
use mcp_server_rs::builder::packaging::{
    ManifestFieldArgs, OpRefs, ToolManifestInput, build_package, kit_source, manifest_fields,
    parse_ops, tool_manifest,
};
use mcp_server_rs::catalog::ids::{AuthorityId, Name, Operation, PositiveVersion, Uuid7};
use mcp_server_rs::catalog::models::{Effect, ExactReference};
use mcp_server_rs::catalog::package::{PackageFile, package_digest};

fn oracle() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/phase5b/oracle.json"
    );
    let text = std::fs::read_to_string(path).expect("the phase-5B fixture file exists");
    serde_json::from_str(&text).expect("the phase-5B fixture file is JSON")
}

fn hex_sha256(text: &str) -> String {
    hex::encode(Sha256::digest(text.as_bytes()))
}

fn object(value: &Value) -> Map<String, Value> {
    value.as_object().cloned().expect("a JSON object")
}

fn reference(value: &Value) -> ExactReference {
    ExactReference {
        id: Uuid7::new(value["id"].as_str().expect("an id")).expect("a uuid7"),
        version: PositiveVersion::new(value["version"].as_u64().expect("a version"))
            .expect("a positive version"),
    }
}

#[test]
fn the_embedded_kit_is_the_reference_kit_byte_for_byte() {
    let fixtures = oracle();
    let kit = &fixtures["kit_source"];
    assert_eq!(kit_source(), kit["text"].as_str().expect("the kit text"));
    assert_eq!(
        hex_sha256(kit_source()),
        kit["sha256"].as_str().expect("the kit digest")
    );
}

#[test]
fn every_preview_row_matches_the_reference() {
    let fixtures = oracle();
    let listed = list_operations(&fixtures["document"], None).expect("the fixed document is valid");
    let actual = serde_json::to_value(&listed).expect("preview rows are JSON");
    assert_eq!(actual, fixtures["operations"]);
}

#[test]
fn the_conversion_matches_the_reference_manifest_and_package() {
    let fixtures = oracle();
    let conversion = &fixtures["conversion"];
    let service = reference(&conversion["service"]);
    let selection: Vec<Selection> = conversion["selection"]
        .as_array()
        .expect("a selection")
        .iter()
        .map(|entry| Selection::from_value(entry).expect("a valid selection"))
        .collect();
    let overrides = conversion["overrides"].as_object().cloned();
    let imported = import_openapi(
        &fixtures["document"],
        &service,
        &selection,
        None,
        overrides.as_ref(),
    )
    .expect("the fixed selection imports");

    // Every imported operation: the script key, the document identity and the draft manifest.
    // The port mints a fresh UUIDv7 per import (`uuid::Uuid::now_v7`); the oracle pins its ids
    // so the fixture is byte-identical across runs, so the minted id is the one field that
    // cannot agree and is replaced with the pinned one before the manifest is compared. The
    // package below is built from the pinned ids for the same reason.
    let expected = conversion["operations"].as_array().expect("operations");
    let prefix = conversion["key_prefix"].as_str().expect("the key prefix");
    assert_eq!(imported.len(), expected.len());
    let mut refs = OpRefs::new();
    let mut references = Vec::new();
    for (actual, expected) in imported.iter().zip(expected) {
        let key = expected["op_key"].as_str().expect("op_key");
        let expected_manifest = &expected["manifest"];
        assert_eq!(actual.op_key, key);
        assert_eq!(
            actual.operation_id.as_deref(),
            expected["operation_id"].as_str()
        );
        assert_eq!(actual.method, expected["method"].as_str().expect("method"));
        assert_eq!(actual.path, expected["path"].as_str().expect("path"));
        assert_eq!(
            actual.summary,
            expected["summary"].as_str().expect("summary")
        );
        let mut manifest = serde_json::to_value(&actual.manifest).expect("a manifest is JSON");
        let pinned = expected_manifest["operation_id"]
            .as_str()
            .expect("the pinned operation id");
        manifest["operation_id"] = Value::String(pinned.to_owned());
        assert_eq!(&manifest, expected_manifest, "{key}");
        let id = Uuid7::new(pinned).expect("a pinned uuid7");
        let version = PositiveVersion::new(expected_manifest["version"].as_u64().expect("version"))
            .expect("a positive version");
        refs.insert(format!("{prefix}.{key}"), (id.clone(), version));
        references.push(ExactReference { id, version });
    }

    // The package: the author files plus the host's regenerated kit.py and ops.py.
    let input_files: Vec<PackageFile> =
        serde_json::from_value(conversion["input_files"].clone()).expect("the author files");
    let built = build_package(&input_files, &refs);
    let package = &conversion["package"];
    let expected_files = package["files"].as_array().expect("package files");
    assert_eq!(built.len(), expected_files.len());
    for (file, expected) in built.iter().zip(expected_files) {
        assert_eq!(file.path, expected["path"].as_str().expect("path"));
        assert_eq!(
            hex_sha256(&file.content),
            expected["sha256"].as_str().expect("sha256"),
            "{}",
            file.path
        );
        assert_eq!(
            file.content.len(),
            expected["bytes"].as_u64().expect("bytes") as usize,
            "{}",
            file.path
        );
    }
    assert_eq!(
        package_digest(&built),
        package["digest"].as_str().expect("the package digest")
    );
    assert_eq!(
        built
            .iter()
            .find(|file| file.path == "ops.py")
            .expect("the host writes ops.py")
            .content,
        fixtures["ops_py"].as_str().expect("the generated ops.py")
    );
    assert_eq!(parse_ops(&built).expect("the generated table parses"), refs);

    // The manifest the host fills in, from the reference's own field defaults.
    let tool = &conversion["tool"];
    let effect = match tool["effect"].as_str().expect("effect") {
        "read_only" => Effect::ReadOnly,
        "writes" => Effect::Writes,
        other => panic!("unknown effect {other}"),
    };
    let public_name =
        Name::new(tool["public_name"].as_str().expect("public_name")).expect("a catalog name");
    let platform_operation = Operation::new(tool["operation"].as_str().expect("operation"))
        .expect("a platform operation");
    let input_schema = object(&tool["input_schema"]);
    let fields = manifest_fields(ManifestFieldArgs {
        public_name: &public_name,
        operation: &platform_operation,
        description: tool["description"].as_str().expect("description"),
        entrypoint: tool["entrypoint"].as_str().expect("entrypoint"),
        input_schema: &input_schema,
        result_schema: None,
        context_schema: None,
        effect,
        limits: None,
    });
    assert_eq!(Value::Object(fields.clone()), conversion["fields"]);
    let tool_id = Uuid7::new(tool["tool_id"].as_str().expect("tool_id")).expect("a uuid7");
    let tenant_id = AuthorityId::new(tool["tenant_id"].as_str().expect("tenant_id"))
        .expect("a tenant identity");
    let manifest = tool_manifest(ToolManifestInput {
        tool_id: &tool_id,
        tenant_id: &tenant_id,
        version: PositiveVersion::new(tool["version"].as_u64().expect("version"))
            .expect("a positive version"),
        fields: &fields,
        files: &built,
        refs: &references,
        runner_image_digest: tool["runner_image_digest"]
            .as_str()
            .expect("the runner image digest"),
    })
    .expect("the assembled manifest is valid");
    assert_eq!(
        serde_json::to_value(&manifest).expect("a manifest is JSON"),
        conversion["tool_manifest"]
    );
}

/// Deserialize one request model; the Rust port's own message for a refused body.
fn model_refusal(model: &str, body: &Value) -> String {
    match model {
        "ToolCreate" => serde_json::from_value::<ToolCreate>(body.clone())
            .expect_err("refused")
            .to_string(),
        "ImportRequest" => serde_json::from_value::<ImportRequest>(body.clone())
            .expect_err("refused")
            .to_string(),
        "OperationOverride" => serde_json::from_value::<OperationOverride>(body.clone())
            .expect_err("refused")
            .to_string(),
        "SpecFetchRequest" => serde_json::from_value::<SpecFetchRequest>(body.clone())
            .expect_err("refused")
            .to_string(),
        "BindRequest" => serde_json::from_value::<BindRequest>(body.clone())
            .expect_err("refused")
            .to_string(),
        "ToolOperation" => serde_json::from_value::<ToolOperation>(body.clone())
            .expect_err("refused")
            .to_string(),
        other => panic!("unknown model {other}"),
    }
}

#[test]
fn every_refusal_matches_the_reference() {
    let fixtures = oracle();
    let service = reference(&fixtures["conversion"]["service"]);
    let cases = fixtures["refusals"].as_array().expect("the refusal table");
    assert!(cases.len() >= 20, "the fixture must carry the full table");
    for case in cases {
        let name = case["name"].as_str().expect("a case name");
        let message = case["message"].as_str().expect("the refusal message");
        match case["kind"].as_str().expect("a case kind") {
            "document" => {
                let error = list_operations(&case["input"], None).expect_err(name);
                assert_eq!(error.reason, message, "{name}");
            }
            "selection_entry" => {
                let error = Selection::from_value(&case["input"]).expect_err(name);
                assert_eq!(error.reason, message, "{name}");
            }
            "select" => {
                let selection: Vec<Selection> = case["selection"]
                    .as_array()
                    .expect("a selection")
                    .iter()
                    .map(|entry| Selection::from_value(entry).expect("a valid selection"))
                    .collect();
                let overrides = case["overrides"].as_object().cloned();
                let error = import_openapi(
                    &fixtures["document"],
                    &service,
                    &selection,
                    None,
                    overrides.as_ref(),
                )
                .expect_err(name);
                assert_eq!(error.reason, message, "{name}");
            }
            "model" => {
                let model = case["model"].as_str().expect("a model name");
                let error = model_refusal(model, &case["input"]);
                assert!(!error.is_empty(), "{name}");
                // The one model validator whose message the port reproduces verbatim; Pydantic
                // prefixes validator errors with "Value error, ".
                if model == "ToolOperation" {
                    let shared = message.strip_prefix("Value error, ").unwrap_or(message);
                    assert!(error.contains(shared), "{name}: {error}");
                }
            }
            other => panic!("unknown refusal kind {other}"),
        }
    }
}
